/**
 * @summary Update current user profile
 */
export const getUpdateMeUrl = () => {
  return `/api/users/me`;
};

export const updateMe = async (
  updateUserRequest: UpdateUserRequest,
  options?: RequestInit,
): Promise<User> => {
  const formData = new FormData();
  if (updateUserRequest.first_name !== undefined) {
    formData.append(`first_name`, updateUserRequest.first_name);
  }
  if (updateUserRequest.last_name !== undefined) {
    formData.append(`last_name`, updateUserRequest.last_name);
  }
  if (updateUserRequest.middle_name !== undefined) {
    formData.append(`middle_name`, updateUserRequest.middle_name);
  }
  if (updateUserRequest.phone !== undefined) {
    formData.append(`phone`, updateUserRequest.phone);
  }
  if (updateUserRequest.password !== undefined) {
    formData.append(`password`, updateUserRequest.password);
  }
  if (updateUserRequest.is_active !== undefined) {
    formData.append(`is_active`, updateUserRequest.is_active.toString());
  }
  if (updateUserRequest.role !== undefined) {
    formData.append(`role`, updateUserRequest.role);
  }
  if (updateUserRequest.photo !== undefined) {
    formData.append(`photo`, updateUserRequest.photo);
  }

  return customFetch<User>(getUpdateMeUrl(), {
    ...options,
    method: "PUT",
    body: formData,
  });
};

