/**
 * @summary Update a user (admin only)
 */
export const getUpdateUserUrl = (id: string) => {
  return `/api/users/${id}`;
};

export const updateUser = async (
  id: string,
  updateUserRequest: UpdateUserRequest,
  options?: RequestInit,
): Promise<User> => {
  const formData = new FormData();
  if (updateUserRequest.first_name !== undefined) {
    formData.append(`first_name`, updateUserRequest.first_name);
  }
  if (updateUserRequest.last_name !== undefined) {
    formData.append(`last_name`, updateUserRequest.last_name);
  }
  if (updateUserRequest.middle_name !== undefined) {
    formData.append(`middle_name`, updateUserRequest.middle_name);
  }
  if (updateUserRequest.phone !== undefined) {
    formData.append(`phone`, updateUserRequest.phone);
  }
  if (updateUserRequest.password !== undefined) {
    formData.append(`password`, updateUserRequest.password);
  }
  if (updateUserRequest.is_active !== undefined) {
    formData.append(`is_active`, updateUserRequest.is_active.toString());
  }
  if (updateUserRequest.role !== undefined) {
    formData.append(`role`, updateUserRequest.role);
  }
  if (updateUserRequest.photo !== undefined) {
    formData.append(`photo`, updateUserRequest.photo);
  }

  return customFetch<User>(getUpdateUserUrl(id), {
    ...options,
    method: "PUT",
    body: formData,
  });
};

export const getUpdateUserMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof updateUser>>,
    TError,
    { id: string; data: BodyType<UpdateUserRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof updateUser>>,
  TError,
  { id: string; data: BodyType<UpdateUserRequest> },
  TContext
> => {
  const mutationKey = ["updateUser"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof updateUser>>,
    { id: string; data: BodyType<UpdateUserRequest> }
  > = (props) => {
    const { id, data } = props ?? {};

    return updateUser(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type UpdateUserMutationResult = NonNullable<
  Awaited<ReturnType<typeof updateUser>>
>;
export type UpdateUserMutationBody = BodyType<UpdateUserRequest>;
export type UpdateUserMutationError = ErrorType<ErrorResponse>;

